// big <-> little-endian and store it in a memory position.  Sizes supported: 1, 2, 4, 8 bytes.
void swap_store(void *dest, const void *pa, int size) {
    uint8_t* pa_ = (uint8_t*)pa;
    uint8_t* pa2_ = malloc((size_t)size);

    bool little_endian = is_little_endian();
    if (little_endian) {
        switch (size) {
            case 8:
                pa2_[0] = pa_[7];
                pa2_[1] = pa_[6];
                pa2_[2] = pa_[5];
                pa2_[3] = pa_[4];
                pa2_[4] = pa_[3];
                pa2_[5] = pa_[2];
                pa2_[6] = pa_[1];
                pa2_[7] = pa_[0];
                break;
            case 4:
                pa2_[0] = pa_[3];
                pa2_[1] = pa_[2];
                pa2_[2] = pa_[1];
                pa2_[3] = pa_[0];
                break;
            case 2:
                pa2_[0] = pa_[1];
                pa2_[1] = pa_[0];
                break;
            case 1:
                pa2_[0] = pa_[1];
                break;
            default:
                fprintf(stderr, "Unhandled size: %d\n", size);
        }
    }
    memcpy(dest, pa2_, size);
    free(pa2_);
}


/* Create a new (empty) frame */
blosc2_frame* blosc2_frame_new(const char* fname) {
  blosc2_frame* new_frame = calloc(1, sizeof(blosc2_frame));
  if (fname != NULL) {
    char* new_fname = malloc(strlen(fname) + 1);  // + 1 for the trailing NULL
    new_frame->fname = strcpy(new_fname, fname);
  }
  return new_frame;
}


/* Free memory from a frame. */
int blosc2_frame_free(blosc2_frame *frame) {

  if (frame->sdata != NULL) {
    free(frame->sdata);
  }

  if (frame->coffsets != NULL) {
    free(frame->coffsets);
  }

  if (frame->fname != NULL) {
    free(frame->fname);
  }

  free(frame);

  return 0;
}


